          '[daemon] Shadow sync: conflict detected. Run `kspec shadow resolve` to fix.'
        );

        if (this.pubsub) {
          this.pubsub.broadcast('shadow', 'shadow_sync', {
            pulled: false,
            hadConflict: true,
          });
        }
      }
    } finally {
      this.running = false;
    }
  }
}

